// === Tab: mySketch ===
let App = {
	mouseSpringConst: 25,
	particles: []
};

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(100);

	App.mouse = new Vector2(0, 0);

	for (let i = 0; i < 500; i++) {
		let particle = new DriftingParticle(random(windowWidth), random(windowHeight), 3, color(255), 0.25);
		particle.spring = new SpringTool(particle.x, particle.y);
		particle.drifter.children.push(particle.spring);
		App.particles.push(particle);
	}
}

function draw() {
	App.mouse.x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
	App.mouse.y = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));

	background(127);

	for (let p of App.particles) {
		pushParticleWithMouse(p);
		p.update();
		p.display();
	}
}

function pushParticleWithMouse(p) {
	let mouseToPoint = Vector2.sub(p, App.mouse);
	let mousePush = new Vector2(mouseToPoint.x, mouseToPoint.y);
	mousePush.setMagnitude(App.mouseSpringConst);
	mousePush.setMagnitude(mousePush.mag / mouseToPoint.mag);
	p.acceleration.add(mousePush);
}

// === Tab: Particle ===
class Vector2 {
	constructor(x, y) {
		this.x = (x !== undefined ? x : 0);
		this.y = (y !== undefined ? y : 0);

		Object.defineProperty(this, 'angle', {
			get: () => { return atan2(this.y, this.x); },
			enumerable: true
		});
		Object.defineProperty(this, 'mag', {
			get: () => { return sqrt(this.x * this.x + this.y * this.y); },
			enumerable: true
		});
	}

	static copy(v) {
		return new Vector2(v.x, v.y);
	}

	static add(v1, v2) {
		return new Vector2(v1.x + v2.x, v1.y + v2.y);
	}

	static sub(v1, v2) {
		return new Vector2(v1.x - v2.x, v1.y - v2.y);
	}

	static dot(v1, v2) {
		return v1.x * v2.x + v1.y * v2.y;
	}

	static distance(v1, v2) {
		return sqrt(sq(v2.x - v1.x) + sq(v2.y - v1.y));
	}

	add(v) {
		this.x += v.x;
		this.y += v.y;
	}

	sub(v) {
		this.x -= v.x;
		this.y -= v.y;
	}

	scale(scaler) {
		this.x *= scaler;
		this.y *= scaler;
	}

	setMagnitude(mag) {
		let angle = this.angle;
		this.x = cos(angle) * mag;
		this.y = sin(angle) * mag;
	}

	scaleMagnitude(scaler) {
		var angle = this.angle;
		let mag = this.mag * scaler;
		this.x = cos(angle) * mag;
		this.y = sin(angle) * mag;
	}

	normalize() {
		var angle = this.angle;
		this.x = cos(angle);
		this.y = sin(angle);
	}

	rotate(rotation) {
		let targetAngle = this.angle + rotation;
		var mag = this.mag;
		this.x = cos(targetAngle) * mag;
		this.y = sin(targetAngle) * mag;
	}
}

class Particle extends Vector2 {
	constructor(x, y, radius, c) {
		super(x, y);

		this.radius = (radius !== undefined ? radius : 5);
		this.color = (c !== undefined ? c : color(255));
		this.outline = color(0, 0);

		this.velocity = new Vector2(0, 0);
		this.acceleration = new Vector2(0, 0);
	}

	update() {
		this.updateSpeed();
		this.move();
	}

	updateSpeed() {
		if (this.hasOwnProperty('spring')) {
			this.spring.applyTension(this);
		}

		this.velocity.add(this.acceleration);
		this.acceleration.scale(0);

		if (this.velocity.mag > this.maxVelocity) {
			this.velocity.setMagnitude(this.maxVelocity);
		}
	}

	move() {
		this.x += this.velocity.x;
		this.y += this.velocity.y;
	}

	display() {
		fill(this.color);
		stroke(this.outline);
		circle(this.x, this.y, this.radius * 2);
	}
}
Particle.prototype.drag = 1;
Particle.prototype.maxVelocity = 20;

class DriftingParticle extends Particle {
	constructor(x, y, radius, c, driftSpeed) {
		super(x, y, radius, c);

		if (driftSpeed === undefined) {
			driftSpeed = 1;
		}
		let driftAngle = random(TWO_PI);
		let driftMag = random(driftSpeed * 2) - driftSpeed;
		this.drift = new Vector2(cos(driftAngle) * driftMag, sin(driftAngle) * driftMag);

		this.drifter = new Vector2Parent(this.x, this.y, this);
	}

	move() {
		super.move();

		let newDriftX = this.drift.x + this.drifter.x;
		if (newDriftX < 0 || newDriftX > windowWidth) {
			this.drift.x *= -1;
		}
		let newDriftY = this.drift.y + this.drifter.y;
		if (newDriftY < 0 || newDriftY > windowHeight) {
			this.drift.y *= -1;
		}
		this.drifter.add(this.drift);
	}
}

// === Tab: Tools ===
class SpringTool extends Vector2 {
	constructor(x, y, tension) {
		super(x, y);

		this.tension = (tension !== undefined ? tension : 1);
	}

	applyTension(p) {
		let diff = Vector2.sub(this, p);
		diff.scaleMagnitude(this.tension * this.springConstant);
		p.acceleration.add(diff);

		let tensionScale = 255 * (1 - diff.mag / this.maxTensionValue);
		p.color = color(255, tensionScale, tensionScale);

		let drag = Vector2.copy(p.velocity);
		drag.setMagnitude(this.springDrag);
		p.acceleration.sub(drag);
	}
}
SpringTool.prototype.springConstant = 0.01;
SpringTool.prototype.springDrag = 0.05;
SpringTool.prototype.maxTensionValue = 1;



class Vector2Parent extends Vector2 {
	constructor(x, y, ...args) {
		super(x, y);

		this.children = [].concat(args);
	}

	add(x, y) {
		var diff = new Vector2(x, y);
		for (let child in this.children) {
			child.add(diff);
		}
		this.x += x;
		this.y += y;
	}

	set(x, y) {
		var diff = new Vector2(x - this.x, y - this.y);
		for (let child of this.children) {
			child.add(diff);
		}
		this.x = x;
		this.y = y;
	}

	add(v) {
		for (let child of this.children) {
			child.add(v);
		}
		this.x += v.x;
		this.y += v.y;
	}

	sub(v) {
		for (let child of this.children) {
			child.sub(v);
		}
		this.x -= v.x;
		this.y -= v.y;
	}

